/*
 * Checked BEFORE anything is written, so a mistyped address creates no account.
 * The address is the identity: trimmed and lower-cased, because the sign-in form
 * finds the account by the address typed into it, and two spellings would be two
 * people. It is the account's username as well as its email (Create User keys on
 * the username), so a second press with the same address finds the account.
 */
const email = String(Inputs.email || '').trim().toLowerCase();
const name = String(Inputs.name || '').trim().replace(/\s+/g, ' ');
const organisation = String(Inputs.organisation || '').trim();
const looksLikeEmail = email.length <= 254 && email.split('@').length === 2 && email.split('@')[1].includes('.') && !email.includes(' ');
if (!name) {
  Outputs.why = 'Give their name, as they would like you to use it.';
  Outputs.refuse();
} else if (!looksLikeEmail) {
  Outputs.why = 'That does not look like an email address. Check it and try again.';
  Outputs.refuse();
} else {
  Outputs.email = email;
  Outputs.name = name;
  Outputs.organisation = organisation;
  Outputs.go();
}

// A coach's account is not a learner: adding it would put a coach on their own roster.
// Create User never makes a staff account, so a staff address always arrives here as an
// EXISTING account, and nothing has been written.
const roles = Array.isArray(Inputs.roles) ? Inputs.roles.map((r) => (r && r.name) || r) : [];
if (roles.includes('staff')) {
  Outputs.why = 'That address belongs to a coach on this site, so it cannot be added as a learner.';
  Outputs.refuse();
} else {
  Outputs.go();
}

/*
 * IDEMPOTENT, IN THIS ORDER, so pressing again heals a half-finished add:
 *   1. the account and its role (before this node)
 *   2. a plan: only if the learner has none. Its steps come from the template through
 *      shared/Steps from template (the same helper the plan builder uses), as DRAFTS:
 *      learners never see an unshared step, so they land on "Richard is preparing your
 *      programme" until he shares one.
 *   3. the welcome email: only when this press made the plan, so a second press
 *      never mails twice.
 * The template is checked BEFORE the plan is made, so a missing one writes nothing.
 */
(async () => {
  try {
    const R = Noodl.Records;
    const q = (c, where) => R.query(c, where, { limit: 2, plain: true });
    const userId = String(Inputs.userId || '');
    if (!userId) throw new Error('no account');
    Outputs.learnerId = userId;

    const plans = await q('Plan', { learner: { equalTo: userId } });
    if (plans.length) {
      Outputs.created = false;
      Outputs.mailed = false;
      Outputs.existing();
      return;
    }

    let template = null;
    const templateId = String(Inputs.templateId || '');
    if (templateId) {
      const found = await q('PlanTemplate', { objectId: { equalTo: templateId } });
      if (found.length !== 1) {
        Outputs.why = 'That plan template no longer exists. Choose another, or start with an empty plan.';
        Outputs.refuse();
        return;
      }
      template = found[0];
    }

    const firstName = String(Inputs.name || '').split(' ')[0];
    const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Paris' });
    const plan = await R.create('Plan', {
      learner: userId,
      title: template ? template.title : firstName + "'s programme",
      status: 'active',
      startedOn: today,
      fromTemplate: template ? template.objectId : null
    }, { plain: true });
    const planId = plan.objectId || plan.id;

    if (template) Outputs.job = { planId, learnerId: userId, templateId: template.objectId };
    else Outputs.mail();
  } catch (e) {
    console.error('[dbu:addLearner plan]', String((e && e.message) || e));
    Outputs.failed();
  }
})();

// Only reached when this press made the plan. The link opens the sign-in page with the
// address filled in: a magic link lasts 15 minutes, and a welcome email is often read the next day.
(async () => {
  try {
    const q = (c, where) => Noodl.Records.query(c, where, { limit: 2, plain: true });
    const email = String(Inputs.email || '');
    const firstName = String(Inputs.name || '').split(' ')[0];
    const callers = Inputs.callerId ? await q('_User', { objectId: { equalTo: String(Inputs.callerId) } }) : [];
    const coach = (callers[0] && callers[0].name) || 'Your coach';
    const coachFirst = coach.split(' ')[0];
    const secret = globalThis._noodl_get_secret ? globalThis._noodl_get_secret('appUrl') : null;
    const appUrl = secret && secret.found ? String(secret.value).replace(/\/$/, '') : '';
    let mailed = false;
    if (appUrl && globalThis._noodl_send_email) {
      const link = appUrl + '/sign-in?email=' + encodeURIComponent(email);
      const text = [
        'Hello ' + firstName + ',',
        '',
        "I'm " + coach + ", and I'll be your coach. I've added you to Digital Bricks University, where your coaching programme lives: our live sessions, your homework, and a place to ask me anything between sessions.",
        '',
        "What happens next: I'm preparing your programme now. When it's ready, your home page shows your first session and your first piece of homework.",
        '',
        'To sign in, open this link and press "Email me a sign-in link". There is no password to remember: each time, we email you a link that signs you in.',
        '',
        link,
        '',
        'See you soon,',
        coachFirst
      ].join('\n');
      const res = await globalThis._noodl_send_email({ to: email, subject: 'Welcome to Digital Bricks University', text });
      mailed = !!(res && res.success);
      if (!mailed) console.error('[dbu:addLearner] welcome email not sent:', res && res.error);
    } else {
      console.error('[dbu:addLearner] no appUrl secret or no mailer: welcome email not sent (run tools/setup-signin.mjs)');
    }
    Outputs.learnerId = String(Inputs.userId || '');
    Outputs.created = true;
    Outputs.mailed = mailed;
    Outputs.done();
  } catch (e) {
    console.error('[dbu:addLearner mail]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
